const rp = (n) => 'Rp ' + String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const from = { Email: 'toko@wander.test', Name: 'Shop' };
const { data } = $input.first().json.body;
const msg = {
  denied: { subject: 'Pembayaran ditolak', body: 'Pembayaran untuk pesanan ' + data.code + ' ditolak oleh bank/penyedia pembayaran. Pesanan Anda masih menunggu pembayaran, silakan coba lagi dengan metode lain.' },
  expired: { subject: 'Pesanan kedaluwarsa', body: 'Batas waktu pembayaran pesanan ' + data.code + ' sudah habis. Pesanan dibatalkan dan stok dikembalikan. Silakan pesan ulang jika masih berminat.' },
  cancelled: { subject: 'Pesanan dibatalkan', body: 'Pembayaran pesanan ' + data.code + ' dibatalkan, sehingga pesanan ikut dibatalkan dan stok dikembalikan.' },
}[data.reason] || { subject: 'Pembayaran bermasalah', body: 'Ada masalah pada pembayaran pesanan ' + data.code + '.' };
const items = data.items.map((i) => '- ' + i.name + ' x' + i.quantity).join('\n');
return [{ json: { From: from, To: [{ Email: data.customer.email, Name: data.customer.name }],
  Subject: msg.subject + ' - ' + data.code,
  Text: 'Halo ' + data.customer.name + ',\n\n' + msg.body + '\n\n' + items + '\nTotal: ' + rp(data.total) + '\n\nLihat pesanan: ' + data.orderUrl } }];
